"        async function fetchStatus() {
            try {
                const res = await fetch(API_BASE + '/api/status');
                if (!res.ok) return;
                const data = await res.json();

                // Update stats cards
                document.getElementById('stat-pnl').innerText = data.metrics.pnl_total;
                document.getElementById('stat-sharpe').innerText = data.metrics.sharpe;
                document.getElementById('stat-maxdd').innerText = data.metrics.max_drawdown;
                document.getElementById('stat-last-signal').innerText = 'ts_ms: ' + (data.metrics.last_signal_ts || '—');
                document.getElementById('stat-equity').innerText = data.metrics.equity;

                // Update signaler badge
                const signalerStatusEl = document.getElementById('stat-signaler-status');
                const badge = document.getElementById('signaler-node-badge');
                const dot = document.getElementById('signaler-dot');
                const badgeText = document.getElementById('signaler-badge-text');

                if (data.signaler_running) {
                    signalerStatusEl.innerHTML = '<span class="w-1.5 h-1.5 rounded-full bg-emerald-400 animate-pulse"></span> ЗАПУЩЕН';
                    signalerStatusEl.className = 'text-xs font-semibold text-emerald-400 mt-2 flex items-center gap-1.5';
                    badge.className = 'flex items-center gap-1.5 text-[11px] text-emerald-400 bg-emerald-500/5 px-2 py-0.5 rounded-md border border-emerald-500/10 font-mono';
                    dot.className = 'w-1 h-1 rounded-full bg-emerald-400 animate-pulse';
                    badgeText.innerText = 'live_node';
                } else {
                    signalerStatusEl.innerHTML = '<span class="w-1.5 h-1.5 rounded-full bg-gray-500"></span> ОСТАНОВЛЕН';
                    signalerStatusEl.className = 'text-xs font-semibold text-gray-400 mt-2 flex items-center gap-1.5';

